package space.controlnet.ae2federation.compat;

import java.util.List;
import net.minecraft.gametest.framework.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.neoforged.neoforge.gametest.PrefixGameTestTemplate;

/** Temporary differential control: the real alloy furnace runs on one joined native AE2 grid. */
@PrefixGameTestTemplate(false)
public final class UselessModCompatGameTests {
    private UselessModCompatGameTests() {}

    @GameTest(templateNamespace = "ae2federation_test", template = "harness_native_smoke", timeoutTicks = 600)
    public static void alloyFurnaceCrafting(GameTestHelper helper) {
        var id = "useless_mod:advanced_alloy_furnace_block";
        var furnace = AddonCraftingScene.block(id);
        var scene = AddonCraftingScene.structure(helper, id, List.of("ae2:1k_crafting_storage"),
                place -> place.setBlock(AddonCraftingScene.PROVIDER, furnace), AddonCraftingScene.PROVIDER,
                entity -> entity != null && entity.getBlockState().is(furnace)).joinedBeforeOrder();
        helper.succeedWhen(scene::tick);
    }
}
